import React, { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import api from "../services/api";
import TweetList from "../components/walls/tweetList";
import { API_ENDPOINTS } from "../services/apiEndpoints";
import Footer from "../components/footer.js";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";

const Tweets = () => {
    const { wallId } = useParams();
    const navigate = useNavigate();
    const [tweets, setTweets] = useState(null);
    const [wall, setWall] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const logoUrl = "/path-to-logo.png"; // Fallback logo if wall.logo is unavailable

    useEffect(() => {
        const fetchWalls = async () => {
            try {
                let response = await api.get(
                    API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId)
                );
                setTweets(response.data);
                response = await api.get(API_ENDPOINTS.GET_WALL_BY_ID(wallId));
                setWall(response.data);
                setLoading(false);
            } catch (err) {
                setError("Failed to load wall");
                setLoading(false);
            }
        };
        fetchWalls();
    }, [wallId]);

    if (loading) return <div>Loading...</div>;
    if (error) return <div>{error}</div>;
    if (!tweets) return <div>Wall not found</div>;

    const handleSaveOrder = async () => {
        try {
            await api.put(API_ENDPOINTS.UPDATE_TWEET_ORDER(wallId), { tweets });
            console.log("Tweet order saved:", tweets); // Debug log
        } catch (err) {
            setError("Failed to save tweet order");
            console.error("Error saving tweet order:", err);
        }
    };

    const onDragEnd = (result) => {
        const { source, destination } = result;

        // If dropped outside the list or in the same position, do nothing
        if (!destination || destination.index === source.index) {
            return;
        }

        // Reorder the tweets array
        const newTweets = Array.from(tweets);
        const [reorderedItem] = newTweets.splice(source.index, 1);
        newTweets.splice(destination.index, 0, reorderedItem);

        // Update with new order (using index as order if no id-based order exists)
        setTweets(newTweets);
    };

    // return (
    //   <div className="p-6">
    //     <div className="flex justify-between items-center mb-6">
    //       <div className="flex items-center">
    //         <img
    //           src={wall?.logo || logoUrl}
    //           alt="Logo"
    //           className="w-10 h-10 mr-2 rounded-full"
    //         />
    //         <h2 className="text-2xl font-bold">{wall?.title || "user's Wall"}</h2>
    //       </div>
    //       <div className="space-x-4">
    //         <button
    //           onClick={() => navigate(`/walls/${wallId}/create-tweet`)}
    //           className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600"
    //         >
    //           Create Tweet
    //         </button>
    //         <button
    //           onClick={() => navigate(`/walls/${wallId}/edit`)}
    //           className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
    //         >
    //           Settings
    //         </button>
    //       </div>
    //     </div>
    //     {tweets && tweets.length > 0 ? (
    //       <TweetList wallId={wallId} tweets={tweets} />
    //     ) : (
    //       "No tweets are added yet."
    //     )}
    //     <Footer socialLinks={wall?.socialLinks} />
    //   </div>
    // );

};

export default Tweets;
